package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

type TierEntry struct {
	TierLimit decimal.Decimal
	TierRate  decimal.Decimal
}

type TierTableStruct struct {
	TierEntry [5]TierEntry // 1-based, ignore 0
}

var tierTable TierTableStruct

var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var salesFile *os.File
var salesScanner *bufio.Scanner
var salesRec SalesRec

func truncateToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func storeComm(v decimal.Decimal) {
	// PIC 9(6)V99: scale 2, 6 integer digits -> truncate
	v = truncateToScale(v, 2)
	// keep low-order digits: if overflow, drop high-order
	// For PIC 9(6)V99, max 999999.99, mod 10^6
	// We can simulate by taking integer representation modulo 10^(6+2)
	// But values here won't overflow; still implement.
	// Use coefficient mod.
	// v = mant * 10^-2. Need mant mod 10^8
	// decimal.Coefficient not exposed easily; use string method
	// Simpler: ifabs >= 1_000_000, mod
	// Use decimal modulo
	modBase := decimal.New(1_00000000, 0) // 10^8
	// get unscaled integer: v *100
	unscaled := v.Shift(2)
	// need to handle sign
	sign := unscaled.Sign()
	if sign < 0 {
		unscaled = unscaled.Neg()
	}
	if unscaled.Cmp(modBase) >= 0 {
		unscaled = unscaled.Mod(modBase)
		if sign < 0 {
			unscaled = unscaled.Neg()
		}
	}
	v = unscaled.Shift(-2)
	WsComm = v
}

func storeTotal(v decimal.Decimal) {
	v = truncateToScale(v, 2)
	// PIC 9(9)V99: 9 integer digits, mod 10^11
	modBase := decimal.New(1, 11) // 10^11 = 100000000000
	unscaled := v.Shift(2)
	sign := unscaled.Sign()
	if sign < 0 {
		unscaled = unscaled.Neg()
	}
	if unscaled.Cmp(modBase) >= 0 {
		unscaled = unscaled.Mod(modBase)
		if sign < 0 {
			unscaled = unscaled.Neg()
		}
	}
	WsTotal = unscaled.Shift(-2)
}

func format_ZZZZZ9_99(d decimal.Decimal, pic string) string {
