	// Determine width = len(pic)
	width := len(pic)
	// Find decimal point
	dotPos := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = pic[:dotPos]
		fracPic = pic[dotPos+1:]
