	}
	// Apply Z suppression: leading zeros replaced with spaces, commas in suppressed zone become spaces
	// Find last Z position
	lastZ := -1
	for i, c := range intPic {
		if c == 'Z' || c == 'z' {
			lastZ = i
		}
	}
	// Iterate intResult from start to lastZ
