			} else {
				suppress = false
			}
		} else if intPic[i] == ',' {
			if suppress {
				// check if all digit positions before next non-comma are suppressed?
				// In COBOL, commas inside suppressed zone become spaces
				// Our suppress flag indicates we haven't hit non-zero yet
				intResult[i] = ' '
			} else {
