func formatWsSalesEd(d decimal.Decimal) string {
	return format_ZZZZZ9_99(d, "ZZZ,ZZ9.99")
}
func formatWsCommEd(d decimal.Decimal) string {
	return format_ZZZZZ9_99(d, "ZZZ,ZZ9.99")
}
func formatWsTotalEd(d decimal.Decimal) string {
	return format_ZZZZZ9_99(d, "ZZZ,ZZZ,ZZ9.99")
}
func formatWsRateEd(d decimal.Decimal) string {
	// PIC 9.99 : width 4, 1 integer digit 9 (zero padded), dot, 2 frac
	d = d.Truncate(2)
	neg := d.Sign() < 0
	if neg {
		d = d.Neg()
	}
	shifted := d.Shift(2).Truncate(0)
	pow10 := decimal.New(1, 2)
	intPart := shifted.Div(pow10).Truncate(0).Mod(decimal.New(1, 1)) // mod 10
	fracPart := shifted.Mod(pow10)
	intStr := intPart.String()
	fracStr := fracPart.String()
	if len(fracStr) < 2 {
		fracStr = strings.Repeat("0", 2-len(fracStr)) + fracStr
	}
	s := intStr + "." + fracStr
	if neg {
		s = "-" + s
	}
	// width 4
	if len(s) < 4 {
		s = strings.Repeat(" ", 4-len(s)) + s
	}
	return s
}

func inputDone() bool {
	return WsEofFlag == "Y"
}

func MAIN_PARA() {
	INIT_PARA()
	var err error
	salesFile, err = os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as EOF
		WsEofFlag = "Y"
	} else {
		defer salesFile.Close()
		salesScanner = bufio.NewScanner(salesFile)
		READ_PARA()
		for !inputDone() {
			PROCESS_PARA()
		}
	}
	SUMMARY_PARA()
}

func INIT_PARA() {
	tierTable.TierEntry[1].TierLimit = decimal.New(100000, -2)
	tierTable.TierEntry[1].TierRate = decimal.New(250, -2)
	tierTable.TierEntry[2].TierLimit = decimal.New(500000, -2)
	tierTable.TierEntry[2].TierRate = decimal.New(400, -2)
	tierTable.TierEntry[3].TierLimit = decimal.New(2000000, -2)
	tierTable.TierEntry[3].TierRate = decimal.New(550, -2)
	tierTable.TierEntry[4].TierLimit = decimal.New(99999999, -2)
	tierTable.TierEntry[4].TierRate = decimal.New(725, -2)
}

func READ_PARA() {
	if salesScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if !salesScanner.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := salesScanner.Text()
	// pad to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	}
	if len(line) > 12 {
		line = line[:12]
	}
	salesRec.SrId = line[0:4]
	digits := line[4:12]
	// PIC 9(6)V99: 8 digits, implied 2 decimals
	var n int64
	for _, ch := range digits {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		} else {
			n = n * 10
		}
	}
	salesRec.SrSales = decimal.New(n, -2)
}

func PROCESS_PARA() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && !(WsTier > 0); WsIdx++ {
		if salesRec.SrSales.Cmp(tierTable.TierEntry[WsIdx].TierLimit) <= 0 {
			WsTier = WsIdx
		}
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE /100
	rate := tierTable.TierEntry[WsTier].TierRate
	comp := salesRec.SrSales.Mul(rate).Shift(-2)
	comp = comp.Round(2)
	storeComm(comp)
	// ADD WS-COMM TO WS-TOTAL
	storeTotal(WsTotal.Add(WsComm))
	WsCount++
	WsSalesEd = formatWsSalesEd(salesRec.SrSales)
	WsRateEd = formatWsRateEd(tierTable.TierEntry[WsTier].TierRate)
	WsCommEd = formatWsCommEd(WsComm)
	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	// WS-TIER is PIC 9 -> prints as single digit without leading spaces? But COBOL DISPLAY numeric unedited prints? For PIC 9, prints zero-padded to width 1 => just digit
	tierStr := fmt.Sprintf("%d", WsTier)
	fmt.Printf("%s T%s %s %s%% %s\n", salesRec.SrId, tierStr, WsSalesEd, WsRateEd, WsCommEd)
	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatWsTotalEd(WsTotal)
	// WS-COUNT is PIC 9(3) : prints zero-padded to 3? In DISPLAY, "REPS: " WS-COUNT
	// Unedited numeric DISPLAY items print zero-padded? The spec says PIC 9(5) prints zero-padded. So PIC 9(3) prints 3 digits zero-padded.
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("REPS: %s TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	MAIN_PARA()
}
